#[test]
fn unit_metadata() {
    let info = MagneticFlux::<f64>::INFO;
    assert_eq!(info.name, "MagneticFlux");
    assert_eq!(info.units.len(), MagneticFluxUnit::ALL.len());
    for (&unit, unit_info) in MagneticFluxUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, MagneticFluxUnit::Weber.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        MagneticFlux::new(v, MagneticFluxUnit::Weber),
        MagneticFlux::from_webers(v)
    );
    assert_eq!(
        MagneticFlux::from_base(v).convert_to(MagneticFluxUnit::Weber),
        MagneticFlux::from_base(v).as_webers()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [MagneticFlux; 1] =
        [MagneticFlux::const_new(1234.5, MagneticFluxUnit::Weber)];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(MagneticFluxUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            MagneticFlux::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in MagneticFluxUnit::ALL {
            assert_eq!(
                MagneticFlux::const_new(v, unit).as_base().to_bits(),
                MagneticFlux::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = MagneticFlux::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            MagneticFlux::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in MagneticFluxUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        MagneticFlux::from_base(0.0).auto_unit().unit,
        MagneticFluxUnit::Weber
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Wb".parse::<MagneticFluxUnit>(),
        Ok(MagneticFluxUnit::Weber)
    );
    assert_eq!(
        format!("2.5 {}", "Wb").parse::<MagneticFlux>(),
        Ok(MagneticFlux::new(2.5, MagneticFluxUnit::Weber))
    );
    assert_eq!(
        "1 not-a-unit".parse::<MagneticFlux>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn parse_every_name() {
    assert_eq!(
        MagneticFluxUnit::from_name("weber"),
        Some(MagneticFluxUnit::Weber)
    );
    assert_eq!(
        MagneticFluxUnit::from_name("weber"),
        Some(MagneticFluxUnit::Weber)
    );
    assert_eq!(
        MagneticFluxUnit::from_name("WEBER"),
        Some(MagneticFluxUnit::Weber)
    );
    assert_eq!(
        MagneticFluxUnit::from_name("webers"),
        Some(MagneticFluxUnit::Weber)
    );
    assert_eq!(
        MagneticFluxUnit::from_name("webers"),
        Some(MagneticFluxUnit::Weber)
    );
    assert_eq!(
        MagneticFluxUnit::from_name("WEBERS"),
        Some(MagneticFluxUnit::Weber)
    );
}

#[test]
fn arithmetic_f64() {
    let a = MagneticFlux::from_base(6.0);
    let b = MagneticFlux::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = MagneticFlux::<i64>::from_base(7);
    let b = MagneticFlux::<i64>::from_base(2);
    assert_eq!(a + b, MagneticFlux::from_base(9));
    assert_eq!(a % b, MagneticFlux::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<MagneticFlux<i64>>(),
        MagneticFlux::from_base(9)
    );
}
